; ============================================================
; Bank $CE: the data the code source does not emit
;
; Generated by tools/extract_data.py from symbols/data_survey.csv;
; do not edit (run `python3 tools/extract_data.py generate`). Each
; piece is a row of the survey (its kind, format, readers and
; confidence are there) at its address. fill and pointer tables are
; source; incbin reads an asset that tools/extract_data.py writes
; from your own ROM to build/assets/, a pack tools/build_rom.py
; makes from one in build/packs/, or text or records it encodes
; into build/text/ and build/records/ (symbols/data_assets.csv
; lists them; nothing here is ROM data).
; ============================================================

; $CE:0000-$CE:00FF (256 B), table, confirmed: 128 u16 offsets of subscripts (bank $CE)
; Read by BattleAct_OpCall.
org $CE0000
BattleRom_ActSubscripts:
    incbin "../../build/records/BattleRom_ActSubscripts.bin"          ; records: table 128 x 2 B

; $CE:0100-$CE:037F (640 B), palette, confirmed: BGR555 colours of the status colour cycles
; Read by BattleCF_StepFxColourCycle.
org $CE0100
BattleRom_FxCycleColours:
    incbin "../../build/assets/palette/BattleRom_FxCycleColours.bin"

; $CE:0380-$CE:8293 (32,532 B), battle_script, confirmed: PC attack and tech action scripts
; Read by BattleAct_LoadScript and its loaders (BattleAct_Load*).
org $CE0380
BattleScript_CE0380:
    incbin "../../build/assets/battle_script/BattleScript_CE0380.bin"

; $CE:8294-$CE:886F (1,500 B), battle_script, confirmed: kind-3 action scripts
; Read by BattleAct_LoadScript and its loaders (BattleAct_Load*).
org $CE8294
BattleScript_CE8294:
    incbin "../../build/assets/battle_script/BattleScript_CE8294.bin"

; $CE:8870-$CE:D427 (19,384 B), table, confirmed: action object records (BattleRom_ActObjRec, 4
; B)
; Read by BattleAct_LoadAttack, BattleAct_LoadKind3, BattleAct_LoadTech, BattleAct_StepObjAnim.
org $CE8870
Table_CE8870:
    incbin "../../build/assets/table/Table_CE8870.bin"

; $CE:D428-$CE:DC19 (2,034 B), battle_script, confirmed: subscripts (opcode $1E)
; Read by BattleAct_LoadScript and its loaders (BattleAct_Load*).
org $CED428
BattleScript_CED428:
    incbin "../../build/assets/battle_script/BattleScript_CED428.bin"

; $CE:DC1A-$CE:DFFF (998 B), padding, confirmed: 998 x $FF
org $CEDC1A
Padding_CEDC1A:
    fillbyte $FF
    fill 998

; $CE:EF11-$CE:EFDF (207 B), text, confirmed: string table (u16 pointers, then TextWin strings)
; Read by BattleCD_ShowMessage, BattleCD_ShowMessageTimed, BattleCD_ShowTargetInfo.
org $CEEF11
BattleRom_MsgStrings:
    incbin "../../build/text/BattleRom_MsgStrings.bin"          ; text unit BattleMessages (strtable)

; $CE:EFE0-$CE:EFE9 (10 B), table, confirmed: 10 B record (bytes 1-9 read)
; Read by BattleCD_EnemyDissolveFx.
org $CEEFE0
BattleRom_DissolveRec:
    incbin "../../build/assets/table/BattleRom_DissolveRec.bin"

; $CE:EFEA-$CE:EFF1 (8 B), table, confirmed: 1 B per pattern 0-7: added to !Battle_DissolvePhase
; per step
; Read by BattleCD_DissolveStep.
org $CEEFEA
BattleRom_DissolvePhaseStep:
    incbin "../../build/records/BattleRom_DissolvePhaseStep.bin"          ; records: table 8 x 1 B

; $CE:EFF2-$CE:EFF9 (8 B), table, confirmed: 2 B per tile set 0-3: VRAM word address
