org $CEEFF2
BattleRom_FxTileVram:
    incbin "../../build/records/BattleRom_FxTileVram.bin"          ; records: table 4 x 2 B

; $CE:EFFA-$CE:EFFB (2 B), table, confirmed: 1 B per colour-math case 0/1:
